sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    if (previous.u_associated_business_markets != '') {
        var delm2m = new GlideRecord('x_hsb11_mss_c_proc_m2m_sys_user_x_hsb11_mss');
        delm2m.addQuery('sys_user', current.sys_id);
        delm2m.query();
        delm2m.deleteMultiple();
    }
    var market = current.u_associated_business_markets;
    if (market != '' || market != undefined) {
        market = market.toString().split(',');
        for (var i = 0; i < market.length; i++) {
            var locCode = new GlideRecord('x_hsb11_mss_c_proc_custody_location_code');
            locCode.addQuery('owning_business', market[i]);
            locCode.addQuery('active', true);
            locCode.query();
            while (locCode.next()) {
                var m2m = new GlideRecord('x_hsb11_mss_c_proc_m2m_sys_user_x_hsb11_mss');
                m2m.initialize();
                m2m.sys_user = current.sys_id;
                m2m.x_hsb11_mss_c_proc_custody_location_code = locCode.sys_id;
                m2m.insert();
            }
        }
    }

})(current, previous);
